-- SAIES Control Tower — Carbon Emissions Update
-- Generated: 2026-05-20 08:05:21
-- Run this on top of your existing saies_warehouse database.
-- It only adds fact_carbon — all other tables are untouched.

USE `saies_warehouse`;

-- ── fact_carbon ─────────────────────────────────────────────
DROP TABLE IF EXISTS `fact_carbon`;
CREATE TABLE IF NOT EXISTS `fact_carbon` (
  `fact_carbon_id`       INT           NOT NULL AUTO_INCREMENT,
  `sales_org_key`        INT               NULL,
  `date_key`             INT               NULL,
  `sim_key`              INT               NULL,
  `ROW_ID`               INT               NULL,
  `TYPE`                 VARCHAR(60)       NULL COMMENT 'Goods Movement, Overhead, Overstock, Products Purchased',
  `SUBTYPE`              VARCHAR(100)      NULL COMMENT 'Goods Receipt, Deliveries, Internal Transfers, etc.',
  `ORIGIN`               VARCHAR(20)       NULL COMMENT 'Warehouse or vendor code',
  `DESTINATION`          VARCHAR(20)       NULL COMMENT 'Warehouse code',
  `PRODUCT`              VARCHAR(20)       NULL COMMENT 'Product code (T01-T06)',
  `MATERIAL_DOCUMENT`    BIGINT            NULL,
  `SCOPE`                INT               NULL COMMENT '1=Direct, 2=Indirect energy, 3=Value chain',
  `EMISSIONS`            DECIMAL(12,4)     NULL COMMENT 'Activity-level CO2e',
  `TOTAL_CO2E_EMISSIONS` DECIMAL(12,4)     NULL COMMENT 'Total CO2e for this record',
  PRIMARY KEY (`fact_carbon_id`),
  CONSTRAINT `fk_fc_sales_org` FOREIGN KEY (`sales_org_key`) REFERENCES `dim_sales_org` (`sales_org_key`),
  CONSTRAINT `fk_fc_date`      FOREIGN KEY (`date_key`)      REFERENCES `dim_date`      (`date_key`),
  CONSTRAINT `fk_fc_sim`       FOREIGN KEY (`sim_key`)       REFERENCES `dim_simulation`(`sim_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
  COMMENT='Carbon emissions per transaction — links to dim_sales_org, dim_date, dim_simulation';


